public class StringInternalsDemo {
    public static void main(String[] args) {
        // Literal creation: stored directly in the String Pool
        String s1 = "Java";
        String s2 = "Java";

        // Explicit heap allocation: bypasses the pool initially
        String s3 = new String("Java");

        // Explicitly interning s3 to retrieve the pooled reference
        String s4 = s3.intern();

        // Reference comparisons
        System.out.println(s1 == s2); // true (both point to the same pooled instance)
        System.out.println(s1 == s3); // false (s3 points to a separate heap object)
        System.out.println(s1 == s4); // true (s4 points to the pooled instance returned by intern())

        // Demonstrating immutability: concat returns a brand new String object
        String base = "Hello";
        String modified = base.concat(" World");
        System.out.println(base);     // "Hello" (original object remains untouched)
        System.out.println(modified); // "Hello World"
    }
}
